const rec = $('Fetch Launch Record').first().json || {};
const rf = rec.fields || rec;
const wantClient = Array.isArray(rf['Client']) ? String(rf['Client'][0] || '').trim() : String(rf['Client'] == null ? '' : rf['Client']).trim();
let cf = {};
try {
  const cl = $('Fetch Launch Client').first().json || {};
  if (Array.isArray(cl.records)) {
    const hit = cl.records.find(function (r) { return r && r.id === wantClient; });
    cf = (hit && hit.fields) ? hit.fields : {};
  } else {
    cf = cl.fields || cl;
  }
} catch (e) { cf = {}; }
const baseId = String(cf['Clayroots Base ID'] || '').trim();
if (!/^app[A-Za-z0-9]{14}$/.test(baseId)) { throw new Error('Launch record ' + (rec.id || '') + ' resolves to no Clayroots Base ID (linked Client: ' + (wantClient || 'none') + '). Nothing was written.'); }
let raw = String(rf['Table ID'] == null ? '' : rf['Table ID']).trim();
if (!raw) { raw = String(rf['Target'] == null ? '' : rf['Target']).trim(); }
const m = raw.match(/tbl[A-Za-z0-9]{14}/);
const tableId = m ? m[0] : '';
if (!tableId) { throw new Error('Launch record ' + (rec.id || '') + ' has no Table ID (and no tbl id inside Target). Nothing was written.'); }
let viewId = String(rf['View'] == null ? '' : rf['View']).trim();
const vm = viewId.match(/viw[A-Za-z0-9]{14}/);
if (vm) { viewId = vm[0]; }
return [{ json: { baseId: baseId, tableId: tableId, viewId: viewId, launchRecordId: rec.id || '', startedAt: $now.toISO() } }];

let trig = 'form';
let baseId = '', tableId = '', viewId = '', launchRecordId = '', startedAt = '';
try {
  const f = $('Rank In Company Form').first().json;
  if (f) { baseId = String(f['Clayroots Base ID'] || '').trim(); tableId = String(f['Table ID'] || '').trim(); viewId = String(f['View ID'] || '').trim(); startedAt = f.submittedAt || ''; }
} catch (e) {}
if (!baseId) {
  try {
    const p = $('Restore Params').first().json;
    if (p) { trig = 'record'; baseId = String(p.baseId || '').trim(); tableId = String(p.tableId || '').trim(); viewId = String(p.viewId || '').trim(); launchRecordId = String(p.launchRecordId || ''); startedAt = p.startedAt || ''; }
  } catch (e) {}
}
const tm = tableId.match(/tbl[A-Za-z0-9]{14}/);
tableId = tm ? tm[0] : tableId;
const vm = viewId.match(/viw[A-Za-z0-9]{14}/);
if (vm) { viewId = vm[0]; }
if (!startedAt) { startedAt = $now.toISO(); }
return [{ json: { baseId: baseId, tableId: tableId, viewId: viewId, launchRecordId: launchRecordId, trigger: trig, startedAt: startedAt } }];

const c = $('Config').first().json;
if (!/^app[A-Za-z0-9]{14}$/.test(c.baseId)) { throw new Error('Clayroots Base ID "' + c.baseId + '" is not a valid Airtable base id (expected app followed by 14 characters). Nothing was written.'); }
if (!/^tbl[A-Za-z0-9]{14}$/.test(c.tableId)) { throw new Error('Table ID "' + c.tableId + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was written.'); }
return [{ json: c }];

const c = $('Head Guard').first().json;
const resp = $input.first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + c.baseId + ': ' + JSON.stringify(resp).slice(0, 400) + '. Nothing was written.'); }
const target = tables.find(function (t) { return t.id === c.tableId; });
if (!target) { throw new Error('Table ' + c.tableId + ' does not exist in base ' + c.baseId + '. Tables there: ' + tables.map(function (t) { return t.name; }).join(', ') + '. Nothing was written.'); }
const name = String(target.name || '');
if (/domains/i.test(name)) { throw new Error("'" + name + "' is a domains table. There are no contacts to rank. Nothing was written."); }
const have = new Set((target.fields || []).map(function (f) { return f.name; }));
if (!have.has('Domain')) { throw new Error("'" + name + "' has no Domain field, so contacts cannot be grouped by company. Nothing was written."); }
if (!have.has('Seniority')) { throw new Error("'" + name + "' has no Seniority field, so contacts cannot be ranked. Nothing was written."); }
const rankExisted = have.has('RankInCompany');
const views = Array.isArray(target.views) ? target.views : [];
let viewId = '', viewName = '', scope = 'whole table';
const wanted = String(c.viewId == null ? '' : c.viewId).trim();
if (wanted) {
  let v = views.find(function (x) { return String(x.id) === wanted; });
  if (!v) { v = views.find(function (x) { return String(x.name).trim().toLowerCase() === wanted.toLowerCase(); }); }
  if (!v) { throw new Error("View '" + wanted + "' does not exist on '" + name + "' (" + target.id + '). Views there: ' + (views.length ? views.map(function (x) { return x.name; }).join(', ') : '(none)') + '. Nothing was written.'); }
  viewId = v.id; viewName = v.name; scope = 'view ' + viewName + ' (' + viewId + ')';
}
return [{ json: { baseId: c.baseId, tableId: c.tableId, tableName: name, viewId: viewId, viewName: viewName, scope: scope, launchRecordId: c.launchRecordId, trigger: c.trigger, startedAt: c.startedAt, rankExisted: rankExisted, needsRankField: !rankExisted } }];

const g = $('Table Guard').first().json;
const resp = $input.first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + g.baseId + ' after creating RankInCompany: ' + JSON.stringify(resp).slice(0, 400) + '. Nothing was written.'); }
const target = tables.find(function (t) { return t.id === g.tableId; });
if (!target) { throw new Error('Table ' + g.tableId + ' is no longer present in base ' + g.baseId + '. Nothing was written.'); }
const have = new Set((target.fields || []).map(function (f) { return f.name; }));
if (!have.has('RankInCompany')) { throw new Error("Could not create the RankInCompany field on '" + target.name + "' (" + target.id + '). Nothing was written.'); }
return [{ json: { created: true } }];

const g = $('Table Guard').first().json;
let created = false;
try { created = !!(($('Verify Rank Field').first().json) || {}).created; } catch (e) { created = false; }
return [{ json: Object.assign({}, g, { rankFieldCreated: created }) }];

const g = $('Rank Field Ready').first().json;
const sd = $getWorkflowStaticData('global');
sd.ricRows = [];
sd.ricPages = 0;
delete sd.ricWrites;
delete sd.ricStats;
const viewParam = g.viewId ? ('&view=' + encodeURIComponent(g.viewId)) : '';
return [{ json: { baseId: g.baseId, tableId: g.tableId, tableName: g.tableName, viewId: g.viewId || '', viewParam: viewParam, offset: '', page: 0, done: false } }];

const cfg = $('Init Read Loop').first().json;
const resp = $input.first().json || {};
if (!Array.isArray(resp.records)) { throw new Error('Airtable read failed on table ' + cfg.tableId + ' in base ' + cfg.baseId + ': ' + JSON.stringify(resp).slice(0, 400) + '. Nothing was written.'); }
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.ricRows)) { sd.ricRows = []; }
function score(v) {
  let s = v;
  if (Array.isArray(s)) { s = s.length ? s[0] : ''; }
  s = String(s == null ? '' : s).trim().toLowerCase();
  if (!s) { return 5; }
  if (s === 'c-suite' || s === 'founder' || s === 'owner' || s === 'president' || s === 'executive') { return 1; }
  if (s === 'vp') { return 2; }
  if (s === 'head' || s === 'director') { return 3; }
  if (s === 'manager') { return 4; }
  return 5;
}
for (let i = 0; i < resp.records.length; i++) {
  const r = resp.records[i];
  const f = r.fields || {};
  const d = String(f.Domain == null ? '' : f.Domain).trim().toLowerCase();
  const cur = Number(f.RankInCompany);
  sd.ricRows.push([r.id, d, score(f.Seniority), (f.RankInCompany == null || isNaN(cur)) ? 0 : cur]);
}
sd.ricPages = (sd.ricPages || 0) + 1;
const off = resp.offset || '';
const done = (!off) || (sd.ricPages >= 1000);
return [{ json: { baseId: cfg.baseId, tableId: cfg.tableId, tableName: cfg.tableName, viewId: cfg.viewId || '', viewParam: cfg.viewParam || '', offset: off, page: sd.ricPages, done: done } }];

const g = $('Rank Field Ready').first().json;
const sd = $getWorkflowStaticData('global');
const rows = Array.isArray(sd.ricRows) ? sd.ricRows : [];
const scanned = rows.length;
const groups = new Map();
let skippedNoDomain = 0;
for (let i = 0; i < rows.length; i++) {
  const t = rows[i];
  if (!t[1]) { skippedNoDomain++; continue; }
  let arr = groups.get(t[1]);
  if (!arr) { arr = []; groups.set(t[1], arr); }
  arr.push(t);
}
const writes = [];
let unchanged = 0, largestDomain = '', largestCount = 0;
const keys = Array.from(groups.keys());
for (let k = 0; k < keys.length; k++) {
  const d = keys[k];
  const list = groups.get(d);
  if (list.length > largestCount) { largestCount = list.length; largestDomain = d; }
  const pos = new Map();
  for (let i = 0; i < list.length; i++) { pos.set(list[i], i); }
  const sorted = list.slice().sort(function (a, b) { return (a[2] - b[2]) || (pos.get(a) - pos.get(b)); });
  for (let i = 0; i < sorted.length; i++) {
    const rank = i + 1;
    if (sorted[i][3] === rank) { unchanged++; continue; }
    writes.push({ id: sorted[i][0], RankInCompany: rank });
  }
}
const stats = { rowsScanned: scanned, companies: groups.size, ranksWritten: writes.length, unchanged: unchanged, skippedNoDomain: skippedNoDomain, largestDomain: largestDomain, largestCount: largestCount, pages: sd.ricPages || 0 };
sd.ricWrites = writes;
sd.ricStats = stats;
delete sd.ricRows;
return [{ json: Object.assign({}, g, stats, { writeCount: writes.length }) }];

const sd = $getWorkflowStaticData('global');
const w = Array.isArray(sd.ricWrites) ? sd.ricWrites : [];
delete sd.ricWrites;
return w.map(function (x) { return { json: x }; });

const items = $input.all();
let fails = 0;
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  if (!j.id || j.error) { fails++; }
}
return [{ json: { writeFailures: fails, attempted: items.length } }];

const g = $('Rank Rows').first().json;
const sd = $getWorkflowStaticData('global');
const st = sd.ricStats || {};
delete sd.ricStats;
delete sd.ricRows;
delete sd.ricWrites;
delete sd.ricPages;
let wf = 0;
try { wf = Number((($('Tally Writes').first().json) || {}).writeFailures) || 0; } catch (e) { wf = 0; }
let clientRec = [];
try { const rc = $('Resolve Client').first().json; if (rc && rc.id) { clientRec = [rc.id]; } } catch (e) {}
let dur = 0;
try { if (g.startedAt) { dur = Math.max(0, Math.round(($now.toMillis() - new Date(g.startedAt).getTime()) / 1000)); } } catch (e) {}
const written = Math.max(0, (st.ranksWritten || 0) - wf);
const fmt = v => Number(v || 0).toLocaleString('en-US');
const parts = [];
parts.push('**' + fmt(written) + ' ranks written across ' + fmt(st.companies || 0) + ' companies**');
parts.push('**Scope**\n- **Table:** ' + g.tableName + ' (' + g.tableId + ')\n- **Scope:** ' + (g.scope || 'whole table') + '\n- **Rows scanned:** ' + fmt(st.rowsScanned || 0) + '\n- **Companies found:** ' + fmt(st.companies || 0));
parts.push('**Ranks**\n- **Written:** ' + fmt(written) + '\n- **Already correct (unchanged):** ' + fmt(st.unchanged || 0) + '\n- **Skipped, no domain:** ' + fmt(st.skippedNoDomain || 0) + '\n- **Write failures:** ' + fmt(wf) + '\n- **Largest company in scope:** ' + (st.largestDomain || 'none') + ' (' + fmt(st.largestCount || 0) + ' contacts)');
parts.push('**Details**\n- **RankInCompany column:** ' + (g.rankFieldCreated ? 'created by this run' : 'already existed') + '\n- **Pages fetched:** ' + fmt(st.pages || 0) + '\n- Idempotent by design: re-running overwrites RankInCompany and only rewrites rows whose rank changed.');
parts.push('**Source:** Rank Contacts (' + (g.trigger === 'record' ? 'record' : 'form') + '-launched)');
const log = {
  'Automation': 'Add rank in company to table',
  'Status': wf ? 'Succeeded with errors' : 'Succeeded',
  'Trigger': 'form',
  'Run at': $now.toISO(),
  'Target': g.tableName + ' (' + g.tableId + ')' + (g.viewId ? (' [view ' + g.viewName + ']') : ''),
  'Records In': st.rowsScanned || 0,
  'Records Out': written,
  'Errors': wf,
  'Duration s': dur,
  'Description': parts.join('\n\n'),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Execution ID': String($execution.id)
};
if (clientRec.length) { log['Client'] = clientRec; } else { delete log['Client']; }
return [{ json: log }];
